+  return parts.map((part, index): ReactNode => {
+    const marker = part.match(/^\[(\d+)]$/)?.[1];
+    const citation = citations.find(
+      (item) => item.marker === Number(marker),
+    );
+    if (!citation || !onCitation) return part;
